package com.bank.qa.bdd;

import io.cucumber.java.en.*;
import static org.junit.jupiter.api.Assertions.*;
import java.math.BigDecimal;

// Each Gherkin step line is bound to a method here.
public class TransferSteps {
    private final Bank bank = new Bank();
    private String error;

    @Given("Rajesh is logged in with balance {int}")
    public void rajeshLoggedIn(int balance) { bank.setBalance("rajesh", new BigDecimal(balance)); }

    @Given("Priya has balance {int}")
    public void priyaBalance(int balance) { bank.setBalance("priya", new BigDecimal(balance)); }

    @When("Rajesh transfers {int} to Priya")
    public void transfer(int amount) {
        error = bank.transfer("rajesh", "priya", new BigDecimal(amount));
    }

    @Then("Rajesh balance is {int}")
    public void rajeshBalanceIs(int expected) {
        assertEquals(0, bank.balance("rajesh").compareTo(new BigDecimal(expected)));
    }

    @Then("Priya balance is {int}")
    public void priyaBalanceIs(int expected) {
        assertEquals(0, bank.balance("priya").compareTo(new BigDecimal(expected)));
    }

    @Then("the transfer is rejected with {string}")
    public void rejectedWith(String msg) { assertEquals(msg, error); }
}
