package com.bank.qa.bdd;

import java.math.BigDecimal;
import java.util.logging.*;

// Simulates how a BDD runner binds Given-When-Then to steps and executes.
public class BddDemo {
    private static final Logger log = Logger.getLogger(BddDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BddLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Bank bank = new Bank();

        log.info("=== Scenario: Successful transfer ===");
        log.info("GIVEN Rajesh logged in with balance 1000000");
        bank.setBalance("rajesh", new BigDecimal("1000000"));
        log.info("AND Priya has balance 250000");
        bank.setBalance("priya", new BigDecimal("250000"));
        log.info("WHEN Rajesh transfers 50000 to Priya");
        String err = bank.transfer("rajesh", "priya", new BigDecimal("50000"));
        log.info("THEN Rajesh balance is 950000 -> "
            + (bank.balance("rajesh").compareTo(new BigDecimal("950000")) == 0 ? "PASS" : "FAIL"));
        log.info("AND Priya balance is 300000 -> "
            + (bank.balance("priya").compareTo(new BigDecimal("300000")) == 0 ? "PASS" : "FAIL"));

        log.info("=== Scenario: Insufficient funds ===");
        Bank bank2 = new Bank();
        bank2.setBalance("rajesh", new BigDecimal("1000"));
        log.info("GIVEN balance 1000; WHEN transfer 50000");
        String err2 = bank2.transfer("rajesh", "priya", new BigDecimal("50000"));
        log.info("THEN rejected with 'Insufficient balance' -> "
            + ("Insufficient balance".equals(err2) ? "PASS" : "FAIL"));

        log.info("Tools: Cucumber (Gherkin) / JBehave bind these English steps to code.");
    }
}

// ─── Would be in BddLogFormatter.java in a real project ───
class BddLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
